WITH session_stats AS (SELECT session_id, COUNT(DISTINCT duration_sec) AS unique_pages, COUNT(CASE WHEN page = '/cart' THEN 1 END) AS cart_count FROM web_events GROUP BY session_id) SELECT sessions.id, sessions.browser, session_stats.unique_pages, session_stats.cart_count FROM sessions LEFT JOIN session_stats ON sessions.id = session_stats.session_id WHERE session_stats.unique_pages >= 6 ORDER BY browser, unique_pages DESC
